package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.special.Beta;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FDistribution_getNumericalMean_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetNumericalMean_DenominatorGreaterThanTwo() throws NotStrictlyPositiveException {
        // Case where denominatorDF > 2
        // Formula: denominatorDF / (denominatorDF - 2)
        // If denominatorDF = 4.0, mean = 4.0 / (4.0 - 2.0) = 2.0
        double numeratorDF = 5.0;
        double denominatorDF = 4.0;
        FDistribution fDistribution = new FDistribution(numeratorDF, denominatorDF);

        double expected = 2.0;
        double actual = fDistribution.getNumericalMean();

        assertEquals(expected, actual, DELTA);
    }








}

