        // Case where denominatorDF == 2
        // Should return Double.NaN because denominatorDF is not > 2
        double numeratorDF = 5.0;
        double denominatorDF = 2.0;
        FDistribution fDistribution = new FDistribution(numeratorDF, denominatorDF);

        double actual = fDistribution.getNumericalMean();

